package tv.vela.launcher;

import android.app.*;import android.content.*;import android.net.Uri;import android.os.*;import android.provider.Settings;import android.view.*;import java.io.*;import java.nio.file.*;import java.security.*;import java.util.*;import org.json.*;

/** Owned emulator only. Signed fixtures are parsed and streamed; installer intents are intercepted. */
public final class LiteUpdateTest extends Instrumentation {
    private Home activity;private String phase="start";private LiteUpdateManager manager;private LiteUpdateManager.Transport originalTransport;
    public static final class Home extends LiteHomeActivity {Intent installer;protected boolean allowAutomaticChecks(){return false;}public void startActivityForResult(Intent i,int request){if(request==902)installer=i;super.startActivityForResult(i,request);}}
    public Activity newActivity(ClassLoader loader,String name,Intent i)throws InstantiationException,IllegalAccessException,ClassNotFoundException{return name.equals(LiteHomeActivity.class.getName())?new Home():super.newActivity(loader,name,i);}
    void check(boolean value,String message){if(!value)throw new AssertionError(message);}
    void ui(Runnable r){runOnMainSync(r);waitForIdleSync();}
    interface Ready {boolean get()throws Exception;}
    void await(Ready r)throws Exception{for(int n=0;n<150;n++){waitForIdleSync();if(r.get())return;Thread.sleep(30);}throw new AssertionError("Timeout: "+phase);}
    void shell(String command)throws Exception{try(ParcelFileDescriptor fd=getUiAutomation().executeShellCommand(command);InputStream in=new ParcelFileDescriptor.AutoCloseInputStream(fd)){while(in.read()!=-1){}}}
    static String hash(File file)throws Exception{MessageDigest h=MessageDigest.getInstance("SHA-256");try(InputStream in=new FileInputStream(file)){byte[] b=new byte[4096];for(int n;(n=in.read(b))!=-1;)h.update(b,0,n);}StringBuilder s=new StringBuilder();for(byte b:h.digest())s.append(String.format(Locale.ROOT,"%02x",b&255));return s.toString();}
    static JSONObject release(File file,String tag,String name,String digest)throws Exception{return new JSONObject().put("tag_name",tag).put("draft",false).put("prerelease",true).put("assets",new JSONArray().put(new JSONObject().put("name",name).put("state","uploaded").put("browser_download_url",LiteReleaseFeed.REPO+"/releases/download/"+tag+"/"+name).put("digest","sha256:"+digest).put("size",file.length())));}
    Object field(Object object,String name)throws Exception{for(Class<?> k=object.getClass();k!=null;k=k.getSuperclass())try{java.lang.reflect.Field f=k.getDeclaredField(name);f.setAccessible(true);return f.get(object);}catch(NoSuchFieldException ignored){}throw new NoSuchFieldException(name);}
    public void onCreate(Bundle args){super.onCreate(args);start();}
    public void onStart(){Bundle result=new Bundle();ActivityMonitor permission=null,installer=null;Context c=getTargetContext();try{
        check(Build.FINGERPRINT.contains("generic")||Build.MODEL.contains("sdk"),"Owned emulator only");check(c.getPackageName().equals("tv.vela.launcher.lite"),"Wrong target");LiteUpdateManager.prefs(c).edit().clear().commit();activity=(Home)startActivitySync(new Intent(c,LiteHomeActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));manager=LiteUpdateManager.get(c);originalTransport=manager.transport;File fixture=new File(c.getExternalFilesDir(null),"update-test/update.apk");check(fixture.isFile(),"Signed update fixture missing");String sha=hash(fixture);JSONObject good=release(fixture,"lite-v99.0.0-fixture","Vela-Lite-99.0.0-fixture.apk",sha);JSONArray feed=new JSONArray().put(release(fixture,"v99.0.0-preview","Vela-99.0.0-preview.apk",sha)).put(good);LiteReleaseFeed.Release r=LiteReleaseFeed.newest(feed,LiteUpdateManager.version(c),true);check(r!=null&&r.version.equals("99.0.0-fixture"),"Full Vela leaked into Lite feed");check(LiteReleaseFeed.newest(new JSONArray().put(good),"999.0.0",true)==null,"Downgrade offered");check(!LiteUpdateManager.allowed("http://github.com/LucasLG92/vela-tv/releases/download/lite-v1/a.apk")&&!LiteUpdateManager.allowed("https://github.com/other/repo/releases/download/lite-v1/a.apk"),"Unsafe update origin allowed");
        phase="automatic-download-and-integrity";check(manager.automatic()&&manager.autoDownload(),"Automatic updates not enabled by default");final int[] calls={0};manager.transport=url->{calls[0]++;return url.equals(LiteReleaseFeed.API)?new ByteArrayInputStream(feed.toString().getBytes("UTF-8")):new FileInputStream(fixture);};ui(manager::check);await(()->!manager.busy()&&manager.ready());check(calls[0]==2,"Unexpected requests or automatic download missing");LiteUpdateManager.verify(c,LiteUpdateManager.apk(c),r);int checked=calls[0];ui(manager::automaticCheck);Thread.sleep(150);check(calls[0]==checked,"Automatic check polled without interval");
        for(String name:new String[]{"wrong-package","wrong-signer"}){File bad=new File(c.getExternalFilesDir(null),"update-test/"+name+".apk");LiteReleaseFeed.Release wrong=new LiteReleaseFeed.Release(r.tag,r.version,r.url,hash(bad),bad.length(),true);boolean rejected=false;try{LiteUpdateManager.verify(c,bad,wrong);}catch(Exception expected){rejected=true;}check(rejected,"Accepted "+name);}
        try(RandomAccessFile file=new RandomAccessFile(LiteUpdateManager.apk(c),"rw")){file.seek(128);int b=file.read();file.seek(128);file.write(b^1);}boolean rejected=false;try{LiteUpdateManager.verify(c,LiteUpdateManager.apk(c),r);}catch(Exception expected){rejected=true;}check(rejected,"Tampered hash accepted");ui(manager::download);await(()->!manager.busy()&&manager.ready());
        phase="permission-return-resumes-installer";shell("appops set tv.vela.launcher.lite REQUEST_INSTALL_PACKAGES deny");IntentFilter pf=new IntentFilter(Settings.ACTION_MANAGE_UNKNOWN_APP_SOURCES);pf.addAction(Settings.ACTION_SECURITY_SETTINGS);pf.addDataScheme("package");permission=addMonitor(pf,new ActivityResult(Activity.RESULT_CANCELED,null),true);IntentFilter af=new IntentFilter(Intent.ACTION_VIEW);af.addDataType("application/vnd.android.package-archive");installer=addMonitor(af,new ActivityResult(Activity.RESULT_CANCELED,null),true);ui(()->manager.requestInstall(activity));check(permission.getHits()==1&&manager.requested(),"Explicit install not retained: hits="+permission.getHits()+", pending="+manager.requested()+", allowed="+activity.getPackageManager().canRequestPackageInstalls());shell("appops set tv.vela.launcher.lite REQUEST_INSTALL_PACKAGES allow");ui(()->{callActivityOnPause(activity);callActivityOnResume(activity);});ActivityMonitor seen=installer;await(()->seen.getHits()==1&&!manager.requested());check(activity.installer!=null&&(activity.installer.getFlags()&Intent.FLAG_GRANT_READ_URI_PERMISSION)!=0&&activity.installer.getClipData()!=null,"Installer URI grant missing");Uri uri=activity.installer.getData();check(uri.toString().equals("content://tv.vela.launcher.lite.updates/update.apk"),"Wrong provider URI");try(ParcelFileDescriptor fd=c.getContentResolver().openFileDescriptor(uri,"r")){check(fd.getStatSize()==fixture.length(),"Provider did not expose exact verified APK");}rejected=false;try{c.getContentResolver().openFileDescriptor(Uri.parse("content://tv.vela.launcher.lite.updates/other"),"r");}catch(FileNotFoundException expected){rejected=true;}check(rejected,"Provider exposed an unrelated path");
        phase="navigation-and-light-appearance";View[] nav=(View[])field(activity,"navigation");ui(nav[2]::requestFocus);sendKeyDownUpSync(KeyEvent.KEYCODE_DPAD_DOWN);waitForIdleSync();check(nav[3].hasFocus(),"Apps did not move to Settings");sendKeyDownUpSync(KeyEvent.KEYCODE_DPAD_UP);waitForIdleSync();check(nav[2].hasFocus(),"Settings did not move back to Apps");
        phase="post-update-cleanup";Files.copy(Paths.get(c.getApplicationInfo().sourceDir),LiteUpdateManager.apk(c).toPath(),StandardCopyOption.REPLACE_EXISTING);LiteUpdateManager.prefs(c).edit().putLong("cleaned",-1).commit();ui(manager::cleanup);check(!LiteUpdateManager.apk(c).exists(),"Installed APK not cleaned automatically");result.putString("result","PASS: isolated Lite release feed, defaults on, one check/download without polling, real signed APK hash/package/signer verification, tamper rejection, explicit permission request survives pause/resume and opens intercepted installer exactly once, URI read grant/provider exact path, installed APK cleanup, Apps ↔ Settings remote navigation. No APK fixture installed, no network request.");
    }catch(Throwable e){result.putString("phase",phase);result.putString("error",android.util.Log.getStackTraceString(e));}finally{if(permission!=null)removeMonitor(permission);if(installer!=null)removeMonitor(installer);if(manager!=null&&originalTransport!=null)manager.transport=originalTransport;LiteUpdateManager.prefs(c).edit().clear().commit();LiteUpdateManager.apk(c).delete();if(activity!=null)ui(activity::finish);}finish(result.containsKey("error")?1:-1,result);}
}
